using System.Text.Json;
using System.Windows;
namespace PhotoTrail.Windows;
public partial class MainWindow {
 LocationAdoptionPlan? locationPlan;int locationRevision;MapPoint? serviceQueryPoint;
 LocationValues ReadLocationValues()=>new(RegionCountry.Text,RegionState.Text,RegionCity.Text,RegionSublocation.Text,RegionCode.Text,RegionIptc.IsChecked==true,RegionOverwrite.IsChecked==true,RegionIndependent.IsChecked==true);
 private void RegionInputChanged(object s,RoutedEventArgs e){if(!IsLoaded)return;locationRevision++;locationPlan=null;if(RegionApply is not null)RegionApply.IsEnabled=false;}
 private async void PreviewManualRegion(object s,RoutedEventArgs e){if(busy||renameRecoveryRequired)return;var selection=Selected;var revision=++locationRevision;locationPlan=null;RegionApply.IsEnabled=false;try{if(InspectorHasInput())throw new InvalidOperationException(L10n.Text("先处理未应用字段输入。"));var input=ReadLocationValues();BeginOperation();var plan=await LocationAdoptionPlan.CreateAsync(selection.Select(r=>r.Document).ToArray(),input,operation!.Token);if(revision!=locationRevision||!Selected.SequenceEqual(selection)||ReadLocationValues()!=input)throw new InvalidOperationException(L10n.Text("选择或手填输入改变。"));locationPlan=plan;RegionStatus.Text=L10n.Message(L10n.Format("独立手填 · {0:yyyy-MM-dd HH:mm:ss} · 冻结{1}张，各自WGS84；{2}；变化字段{3}。尚未加入草稿。",plan.Created,plan.Rows.Length,(input.Overwrite?L10n.Text("明确覆盖"):L10n.Text("仅补缺项，已有文字保持")),plan.Rows.Sum(r=>r.Fields.Count)));}catch(Exception error){RegionStatus.Text=L10n.Message(L10n.Text("地区未冻结：")+L10n.Message(error.Message));}finally{if(busy)EndOperation();RegionApply.IsEnabled=locationPlan is not null&&!renameRecoveryRequired;}}
 private async void ApplyManualRegion(object s,RoutedEventArgs e){if(busy||renameRecoveryRequired||locationPlan is not {} plan)return;try{var input=ReadLocationValues();if(input!=plan.Values)throw new InvalidOperationException(L10n.Text("输入已变化，请重冻结。"));plan.Require(Selected.Select(r=>r.Document).ToArray());await ApplyMetadataBatch("手填地区",(docs,_,token)=>{token.ThrowIfCancellationRequested();plan.Require(docs);foreach(var (doc,i) in docs.Select((d,i)=>(d,i))){token.ThrowIfCancellationRequested();doc.StageDraft(plan.Rows[i].Fields);}return Task.FromResult(new BatchDetails());},()=>ReferenceEquals(locationPlan,plan)&&ReadLocationValues()==input&&!InspectorHasInput());RegionStatus.Text=L10n.Message(Status.Text);locationPlan=null;RegionApply.IsEnabled=false;}catch(Exception error){locationPlan=null;RegionApply.IsEnabled=false;RegionStatus.Text=L10n.Message(L10n.Text("地区未采用：")+L10n.Message(error.Message));}}
}
